local a=2250661
local c=234011
local s=13706571
local m=16777216
local ab="4ZUS0tFad/IPh2eb1u9Wyk5znRQ8oHVlxfwTXprOq7N6+YAEg3smCDcivjGLKJMB"
local p=""

local std="ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
local rev={}
for i = 1, 64 do
	rev[string.byte(ab, i)] = string.byte(std, i)
end

local function unscramble(str)
	local out = {}
	for i = 1, #str do
		local ch = string.byte(str, i)
		local r = rev[ch]
		out[i] = r and string.char(r) or string.char(ch)
	end
	return table.concat(out)
end

local function xorByte(x, y)
	local result = 0
	local place = 1
	for _ = 1, 8 do
		local xb = x % 2
		local yb = y % 2
		if xb ~= yb then
			result = result + place
		end
		x = (x - xb) / 2
		y = (y - yb) / 2
		place = place * 2
	end
	return result
end

local rp = string.reverse(p)
local std64 = unscramble(rp)
local xored = game:GetService("HttpService"):Base64Decode(std64)

local state = s
local bytes = {}
for i = 1, #xored do
	state = (a * state + c) % m
	local kb = (state - (state % 65536)) / 65536
	bytes[i] = string.char(xorByte(string.byte(xored, i), kb))
end

local src = table.concat(bytes)
local f = loadstring(src)
if f then
	f()
end
